using Flow4Tech.Cardapio.Application;
using Flow4Tech.Cardapio.Domain;

namespace Flow4Tech.Api;

/// <summary>The template of the sheet: the columns, the row types, a small valid example (CSV with ";") and the limits.</summary>
internal sealed record ModeloDaImportacaoDto(List<string> Colunas, List<string> Tipos, List<string> Formatos, string ExemploCsv, int LinhasMaximas, int BytesMaximos);

/// <summary>
/// A sheet sent as JSON: <c>Formato</c> is <c>csv</c> or <c>xlsx</c>, <c>ConteudoBase64</c> the file bytes in base64 (up to 1 MiB of file). <c>ImportacaoId</c> is generated by the client (UUID v7):
/// sending it again with the same file answers the first result and writes nothing.
/// </summary>
internal sealed record PreviaDaImportacaoRequest(string? Formato, string? ConteudoBase64);

internal sealed record AplicarImportacaoRequest(Guid ImportacaoId, string? Formato, string? ConteudoBase64);

/// <summary>A problem of one row: its line in the file, the template column, and a message in Portuguese. <c>Coluna</c> is empty when it is about the whole sheet.</summary>
internal sealed record ErroDeLinhaDto(int Linha, string Coluna, string Mensagem);

/// <summary>What one data row does. <c>Tipo</c> is categoria, produto, grupo or opcao; <c>Acao</c> is <c>criar</c>, <c>atualizar</c> or <c>sem-mudanca</c>.</summary>
internal sealed record ItemDaPreviaDto(string Tipo, string Chave, string Acao, int Linha);

internal sealed record ResumoDaImportacaoDto(
    int CategoriasCriadas,
    int CategoriasAtualizadas,
    int ProdutosCriados,
    int ProdutosAtualizados,
    int GruposCriados,
    int GruposAtualizados,
    int OpcoesCriadas,
    int OpcoesAtualizadas);

/// <summary>The preview, or the report of a refused apply: <c>Valida</c> is false when <c>Erros</c> is not empty. Nothing was written.</summary>
internal sealed record PreviaDaImportacaoDto(bool Valida, List<ErroDeLinhaDto> Erros, List<ItemDaPreviaDto> Itens, ResumoDaImportacaoDto Resumo);

/// <summary><c>JaAplicada</c> is true when the import id had already been applied (same file): <c>Resumo</c> is the first result and nothing was written again.</summary>
internal sealed record ImportacaoAplicadaDto(Guid ImportacaoId, bool JaAplicada, ResumoDaImportacaoDto Resumo);

/// <summary>
/// Codes: <c>formato-invalido</c>, <c>arquivo-invalido</c>, <c>arquivo-grande</c>, <c>linhas-demais</c>, <c>arquivo-com-macro</c>, <c>arquivo-com-formula</c> (with <c>Linha</c>), <c>invalido</c> (400);
/// <c>importacao-id-reutilizado</c>, <c>cardapio-desatualizado</c> (409).
/// </summary>
internal sealed record ImportacaoErro(string Codigo, int? Linha = null);

internal static class CardapioImportacaoEndpoints
{
    // 1 MiB of file is 1.4 MiB in base64.
    private const long Body = 1_500_000;

    public static void MapImportacaoDoCardapio(this IEndpointRouteBuilder app)
    {
        ArgumentNullException.ThrowIfNull(app);

        app.MapGet("/cardapio/importacao/modelo", () => Results.Ok(new ModeloDaImportacaoDto(
                [.. ModeloDaImportacao.Colunas],
                [.. ModeloDaImportacao.Tipos],
                ["csv", "xlsx"],
                ModeloDaImportacao.ExemploCsv,
                ModeloDaImportacao.LinhasMaximas,
                ModeloDaImportacao.BytesMaximos)))
            .WithName("modeloDaImportacaoDoCardapio")
            .RequireSession()
            .RequirePermission(ImportacaoPermissions.Importar)
            .Produces<ModeloDaImportacaoDto>()
            .Produces(StatusCodes.Status401Unauthorized)
            .Produces(StatusCodes.Status403Forbidden);

        // Reads and checks every row against the menu and says what would be created or updated. Writes nothing (no row, no audit record, no event).
        app.MapPost("/cardapio/importacao/previa", async (PreviaDaImportacaoRequest body, RequestContextAccessor request, GestaoDaImportacao importacao, CancellationToken cancellationToken) =>
            {
                if (Arquivo(body.Formato, body.ConteudoBase64) is not var (formato, conteudo))
                {
                    return Results.Json(new ImportacaoErro("formato-invalido"), statusCode: StatusCodes.Status400BadRequest);
                }

                var r = await importacao.ValidarAsync(request, formato, conteudo, cancellationToken);
                return r.Resultado == ResultadoDaImportacao.ArquivoInvalido ? ErroDeArquivo(r.Leitura!) : Results.Ok(Previa(r.Plano!));
            })
            .WithName("previaDaImportacaoDoCardapio")
            .RequireSession()
            .WithBodyLimit(Body)
            .RequirePermission(ImportacaoPermissions.Importar)
            .Produces<PreviaDaImportacaoDto>()
            .Produces<ImportacaoErro>(StatusCodes.Status400BadRequest)
            .Produces(StatusCodes.Status401Unauthorized)
            .Produces(StatusCodes.Status403Forbidden);

        // All or nothing and idempotent by ImportacaoId. 201 when applied, 200 when the id had already been applied, 422 with the report when a row is wrong.
        app.MapPost("/cardapio/importacao", async (AplicarImportacaoRequest body, RequestContextAccessor request, GestaoDaImportacao importacao, CancellationToken cancellationToken) =>
            {
                if (Arquivo(body.Formato, body.ConteudoBase64) is not var (formato, conteudo))
                {
                    return Results.Json(new ImportacaoErro("formato-invalido"), statusCode: StatusCodes.Status400BadRequest);
                }

                var r = await importacao.AplicarAsync(request, body.ImportacaoId, formato, conteudo, cancellationToken);
                return r.Resultado switch
                {
                    ResultadoDaImportacao.Ok => Results.Json(new ImportacaoAplicadaDto(body.ImportacaoId, false, Dto(r.Resumo!)), statusCode: StatusCodes.Status201Created),
                    ResultadoDaImportacao.JaAplicada => Results.Ok(new ImportacaoAplicadaDto(body.ImportacaoId, true, Dto(r.Resumo!))),
                    ResultadoDaImportacao.ComErros => Results.Json(Previa(r.Plano!), statusCode: StatusCodes.Status422UnprocessableEntity),
                    ResultadoDaImportacao.ArquivoInvalido => ErroDeArquivo(r.Leitura!),
                    ResultadoDaImportacao.IdReutilizado => Results.Json(new ImportacaoErro("importacao-id-reutilizado"), statusCode: StatusCodes.Status409Conflict),
                    ResultadoDaImportacao.Desatualizada => Results.Json(new ImportacaoErro("cardapio-desatualizado"), statusCode: StatusCodes.Status409Conflict),
                    ResultadoDaImportacao.Negado => Results.StatusCode(StatusCodes.Status403Forbidden),
                    _ => Results.Json(new ImportacaoErro("invalido"), statusCode: StatusCodes.Status400BadRequest),
                };
            })
            .WithName("importarCardapio")
            .RequireSession()
            .WithBodyLimit(Body)
            .RequirePermission(ImportacaoPermissions.Importar)
            .Produces<ImportacaoAplicadaDto>(StatusCodes.Status201Created)
            .Produces<ImportacaoAplicadaDto>()
            .Produces<ImportacaoErro>(StatusCodes.Status400BadRequest)
            .Produces(StatusCodes.Status401Unauthorized)
            .Produces(StatusCodes.Status403Forbidden)
            .Produces<ImportacaoErro>(StatusCodes.Status409Conflict)
            .Produces<PreviaDaImportacaoDto>(StatusCodes.Status422UnprocessableEntity);
    }

    private static (FormatoDePlanilha Formato, byte[] Conteudo)? Arquivo(string? formato, string? base64)
    {
        var f = formato?.Trim().ToUpperInvariant() switch
        {
            "CSV" => FormatoDePlanilha.Csv,
            "XLSX" => FormatoDePlanilha.Xlsx,
            _ => (FormatoDePlanilha?)null,
        };
        if (f is null || string.IsNullOrEmpty(base64))
        {
            return null;
        }

        var bytes = new byte[base64.Length / 4 * 3 + 3];
        return Convert.TryFromBase64String(base64, bytes, out var escritos) ? (f.Value, bytes[..escritos]) : null;
    }

    private static IResult ErroDeArquivo(LeituraDaPlanilha leitura) => Results.Json(
        new ImportacaoErro(
            leitura.Erro switch
            {
                ErroDeLeitura.ArquivoGrande => "arquivo-grande",
                ErroDeLeitura.LinhasDemais => "linhas-demais",
                ErroDeLeitura.ComMacro => "arquivo-com-macro",
                ErroDeLeitura.ComFormula => "arquivo-com-formula",
                _ => "arquivo-invalido",
            },
            leitura.Linha == 0 ? null : leitura.Linha),
        statusCode: StatusCodes.Status400BadRequest);

    private static PreviaDaImportacaoDto Previa(PlanoDaImportacao plano) => new(
        plano.Valido,
        [.. plano.Erros.Select(e => new ErroDeLinhaDto(e.Linha, e.Coluna, e.Mensagem))],
        [.. plano.Itens.Select(i => new ItemDaPreviaDto(i.Tipo, i.Chave, i.Acao switch { AcaoDaImportacao.Criar => "criar", AcaoDaImportacao.Atualizar => "atualizar", _ => "sem-mudanca" }, i.Linha))],
        Dto(plano.Resumo));

    private static ResumoDaImportacaoDto Dto(ResumoDaImportacao r) =>
        new(r.CategoriasCriadas, r.CategoriasAtualizadas, r.ProdutosCriados, r.ProdutosAtualizados, r.GruposCriados, r.GruposAtualizados, r.OpcoesCriadas, r.OpcoesAtualizadas);
}
